import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    def _delete_downloaded_zip():
        try:
            if os.path.exists(save_path):
                os.remove(save_path)
        except OSError as cleanup_error:
            return f"Error: Failed to delete downloaded ZIP file: {cleanup_error}"
        return None

    try:
        if save_path:
            save_dir = os.path.dirname(save_path)
            if save_dir:
                os.makedirs(save_dir, exist_ok=True)
        os.makedirs(extract_path, exist_ok=True)
    except OSError as e:
        return f"Error: Failed to create required directory: {e}"

    try:
        with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
            while True:
                chunk = response.read(8192)
                if not chunk:
                    break
                out_file.write(chunk)
    except urllib.error.URLError as e:
        reason = getattr(e, "reason", None)
        if reason is None:
            reason = str(e)
        cleanup_error = _delete_downloaded_zip()
        message = f"URL Error: {reason}"
        if cleanup_error:
            return f"{message}; {cleanup_error}"
        return message
    except ValueError as e:
        cleanup_error = _delete_downloaded_zip()
        message = f"URL Error: {e}"
        if cleanup_error:
            return f"{message}; {cleanup_error}"
        return message
    except OSError as e:
        cleanup_error = _delete_downloaded_zip()
        message = f"Error: Failed to save downloaded file: {e}"
        if cleanup_error:
            return f"{message}; {cleanup_error}"
        return message

    extraction_error = None
    try:
        with zipfile.ZipFile(save_path, "r") as zip_ref:
            zip_ref.extractall(extract_path)
    except zipfile.BadZipFile:
        extraction_error = "Error: Corrupted ZIP file"
    except zipfile.LargeZipFile as e:
        extraction_error = f"Error: Failed to extract ZIP file: {e}"
    except OSError as e:
        extraction_error = f"Error: Failed to extract ZIP file: {e}"

    cleanup_error = _delete_downloaded_zip()
    if cleanup_error:
        if extraction_error:
            return f"{extraction_error}; {cleanup_error}"
        return cleanup_error

    if extraction_error:
        return extraction_error

    return extract_path
